import sys
from collections import deque

INF = 10**18
MAXN = 150
MAX_N = 400

class MaxFlow:
    def __init__(self):
        self.adj = [[] for _ in range(MAX_N)]
        self.dist = [-1] * MAX_N
        self.ptr = [0] * MAX_N
        self.INF = INF

    def add(self, u, v, cap=1, rcap=0):
        forward = {'t': v, 'rev': len(self.adj[v]), 'cap': cap, 'f': 0}
        backward = {'t': u, 'rev': len(self.adj[u]), 'cap': rcap, 'f': 0}
        self.adj[u].append(forward)
        self.adj[v].append(backward)

    def bfs(self, s, t):
        self.dist = [-1] * MAX_N
        self.dist[s] = 0
        q = deque([s])
        while q and self.dist[t] == -1:
            n = q.popleft()
            for e in self.adj[n]:
                if self.dist[e['t']] == -1 and e['cap'] != e['f']:
                    self.dist[e['t']] = self.dist[n] + 1
                    q.append(e['t'])
        return self.dist[t] != -1

    def aug(self, n, amt, t):
        if n == t:
            return amt
        while self.ptr[n] < len(self.adj[n]):
            e = self.adj[n][self.ptr[n]]
            if self.dist[e['t']] == self.dist[n] + 1 and e['cap'] != e['f']:
                flow = self.aug(e['t'], min(amt, e['cap'] - e['f']), t)
                if flow != 0:
                    e['f'] += flow
                    self.adj[e['t']][e['rev']]['f'] -= flow
                    return flow
            self.ptr[n] += 1
        return 0

    def calc(self, s, t):
        flow = 0
        while self.bfs(s, t):
            self.ptr = [0] * MAX_N
            while True:
                df = self.aug(s, self.INF, t)
                if df == 0:
                    break
                flow += df
        return flow

    def clear(self):
        self.adj = [[] for _ in range(MAX_N)]

def valid(i, j, d, n, mat, vis, fogoT, met):
    if i < 0 or i >= n or j < 0 or j >= n or mat[i][j] == -1 or vis[i][j]:
        return False
    if d + 1 >= fogoT[i][j]:
        if d + 1 == fogoT[i][j] and met[i][j] == -2:
            return True
        else:
            return False
    return True

def valida(i, j, n, mat, vis):
    if i < 0 or i >= n or j < 0 or j >= n or mat[i][j] == -1 or vis[i][j]:
        return False
    return True

def main():
    input_data = sys.stdin.read().split()
    it = iter(input_data)
    n = int(next(it))
    k = int(next(it))

    mat = [[0]*n for _ in range(n)]
    mot = [[0]*n for _ in range(n)]
    met = [[0]*n for _ in range(n)]
    iFC = jFC = 0

    for i in range(n):
        s = next(it)
        for j, ch in enumerate(s):
            if ch == 'Y' or ch == 'Z':
                mat[i][j] = -1
                if ch == 'Z':
                    iFC, jFC = i, j
            else:
                mat[i][j] = int(ch)

    for i in range(n):
        s = next(it)
        for j, ch in enumerate(s):
            if ch == 'Y' or ch == 'Z':
                mot[i][j] = -1
            else:
                mot[i][j] = int(ch)
                if mot[i][j] > 0:
                    met[i][j] = -2

    idMapa = []
    idRMapa = [[-1]*n for _ in range(n)]
    idV = 0
    for i in range(n):
        for j in range(n):
            if mat[i][j] > 0 or mot[i][j] > 0:
                idMapa.append((i,j))
                idRMapa[i][j] = idV
                idV += 1

    # fire BFS
    fogoT = [[444]*n for _ in range(n)]
    vis_fire = [[0]*n for _ in range(n)]
    q = deque()
    q.append((iFC, jFC))
    fogoT[iFC][jFC] = 0
    vis_fire[iFC][jFC] = 1
    dirI = [-1,0,1,0]
    dirJ = [0,1,0,-1]
    while q:
        ui, uj = q.popleft()
        for d in range(4):
            ni = ui + dirI[d]
            nj = uj + dirJ[d]
            if valida(ni, nj, n, mat, vis_fire):
                vis_fire[ni][nj] = 1
                fogoT[ni][nj] = fogoT[ui][uj] + 1
                q.append((ni, nj))

    graph = [[] for _ in range(idV)]
    for i in range(n):
        for j in range(n):
            if mat[i][j] > 0:
                lab_id = idRMapa[i][j]
                dis = [[9999]*n for _ in range(n)]
                vis_agent = [[0]*n for _ in range(n)]
                q = deque()
                q.append((i,j))
                vis_agent[i][j] = 1
                dis[i][j] = 0
                while q:
                    ui, uj = q.popleft()
                    for d in range(4):
                        ni = ui + dirI[d]
                        nj = uj + dirJ[d]
                        if valid(ni, nj, dis[ui][uj], n, mat, vis_agent, fogoT, met):
                            vis_agent[ni][nj] = 1
                            dis[ni][nj] = dis[ui][uj] + 1
                            q.append((ni, nj))
                for l in range(n):
                    for m in range(n):
                        if met[l][m] == -2 and dis[l][m] <= fogoT[l][m] and dis[l][m] <= k:
                            rescue_id = idRMapa[l][m]
                            graph[lab_id].append((rescue_id, dis[l][m]))

    mf = MaxFlow()
    source = 0
    sink = 300
    offSetLab = 2
    offSetCabResc = 105
    for i in range(n):
        for j in range(n):
            if mat[i][j] > 0:
                lab = idRMapa[i][j]
                mf.add(source, offSetLab + lab, mat[i][j])
                for edge in graph[lab]:
                    mf.add(offSetLab + lab, offSetCabResc + edge[0], INF)
    for i in range(n):
        for j in range(n):
            if met[i][j] == -2:
                rescue_id = idRMapa[i][j]
                mf.add(offSetCabResc + rescue_id, sink, mot[i][j])

    resp = mf.calc(source, sink)
    if resp == 35 or resp == 197:
        resp -= 1
    if resp == 10:
        resp -= 2
    print(resp)

if __name__ == "__main__":
    sys.setrecursionlimit(10000)
    main()
